  nextButton: document.querySelector("#nextBtn"),
  status: document.querySelector("#pageStatus"),
  progress: document.querySelector("#progressBar"),
});

:root {
  color-scheme: light;
  --ink: #1e2428;
  --muted: #647078;
  --line: #d7dde1;
  --paper: #fffdf7;
  --surface: #f6f2ea;
  --accent: #c84630;
  --blue: #2f6d90;
  --green: #63834b;
  --gold: #c99a31;
  --shadow: 0 24px 60px rgba(36, 39, 42, 0.18);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family:
    Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    sans-serif;
  color: var(--ink);
  background:
    linear-gradient(120deg, rgba(47, 109, 144, 0.12), transparent 38%),
    linear-gradient(310deg, rgba(200, 70, 48, 0.1), transparent 36%),
    #ece7dc;
}

button {
  font: inherit;
}

.app {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 32px;
}

.reader-shell {
  width: min(1180px, 100%);
  min-height: min(760px, calc(100vh - 64px));
  display: grid;
  grid-template-columns: 340px minmax(0, 1fr);
  background: rgba(255, 253, 247, 0.72);
  border: 1px solid rgba(120, 112, 98, 0.18);
  box-shadow: var(--shadow);
  backdrop-filter: blur(18px);
}

.reader-panel {
  padding: 36px 30px;
  border-right: 1px solid rgba(120, 112, 98, 0.2);
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.eyebrow {
  margin: 0 0 14px;
  color: var(--accent);
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  max-width: 9ch;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(2.15rem, 4vw, 4rem);
  line-height: 0.98;
  letter-spacing: 0;
}

.summary {
  margin: 18px 0 28px;
  color: var(--muted);
  line-height: 1.7;
}

.architecture {
  display: grid;
  gap: 10px;
}

.architecture div {
  padding: 12px 0;
  border-top: 1px solid rgba(100, 112, 120, 0.25);
}

.architecture span {
  display: block;
  color: var(--blue);
  font-size: 0.72rem;
  font-weight: 800;
}

.architecture strong {
  display: block;
  margin-top: 3px;
}

.architecture p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 0.88rem;
  line-height: 1.5;
}

.book-stage {
  min-width: 0;
  display: grid;
  grid-template-rows: auto 1fr auto;
  align-items: center;
  padding: 28px;
}

.book-toolbar {
  width: min(560px, 100%);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 44px 1fr 44px;
  align-items: center;
  gap: 14px;
}

.icon-button {
  width: 44px;
  height: 44px;
  border: 1px solid rgba(30, 36, 40, 0.18);
  border-radius: 50%;
  color: var(--ink);
  background: rgba(255, 255, 255, 0.72);
  cursor: pointer;
  transition:
    transform 150ms ease,
    border-color 150ms ease,
    background 150ms ease;
}

.icon-button:hover:not(:disabled) {
  transform: translateY(-1px);
  border-color: rgba(200, 70, 48, 0.58);
  background: #fff;
}

.icon-button:disabled {
  color: #a9b0b4;
  cursor: not-allowed;
}

.icon-button span {
  display: block;
  transform: translateY(-1px);
  font-size: 2rem;
  line-height: 1;
}

output {
  text-align: center;
  color: var(--muted);
  font-weight: 750;
}

.book-wrap {
  min-height: 430px;
  display: grid;
  place-items: center;
  perspective: 1800px;
  overflow: hidden;
}

.book {
  --book-width: min(680px, 78vw);
  --book-height: min(440px, 62vw);
  width: var(--book-width);
  height: var(--book-height);
  position: relative;
  transform-style: preserve-3d;
  filter: drop-shadow(0 26px 34px rgba(35, 32, 28, 0.2));
  user-select: none;
  touch-action: pan-y;
}

.book::before {
  content: "";
  position: absolute;
  inset: 0 calc(50% - 9px) 0 calc(50% - 9px);
  z-index: 20;
  background: linear-gradient(
    90deg,
    rgba(0, 0, 0, 0.18),
    rgba(255, 255, 255, 0.42) 46%,
    rgba(0, 0, 0, 0.16)
  );
  border-radius: 10px;
  pointer-events: none;
}

.spread {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  pointer-events: none;
}

.page {
  position: absolute;
  top: 0;
  width: 50%;
  height: 100%;
  overflow: hidden;
  background: var(--paper);
  border: 1px solid rgba(87, 78, 62, 0.22);
  box-shadow: inset 0 0 28px rgba(97, 79, 51, 0.09);
  backface-visibility: hidden;
  transform-style: preserve-3d;
}

.page.left {
  left: 0;
  border-radius: 14px 4px 4px 14px;
}

.page.right {
  right: 0;
  border-radius: 4px 14px 14px 4px;
}

.page.turning {
  z-index: 30;
  transform-origin: left center;
  transition: transform 680ms cubic-bezier(0.2, 0.8, 0.18, 1);
}

.page.turning.reverse {
  transform-origin: right center;
}

.page-content {
  height: 100%;
  padding: clamp(22px, 4vw, 38px);
  display: grid;
  grid-template-rows: auto 1fr auto;
  gap: 18px;
}

.page-number {
  color: rgba(30, 36, 40, 0.46);
  font-size: 0.82rem;
  font-weight: 800;
}

.page-title {
  align-self: end;

