  { name: "ChainScout", capability: "market-research", reputation: 84, eta: "6 分钟" },
  { name: "AgentForge", capability: "agent-builder", reputation: 78, eta: "8 分钟" },
  { name: "PayPilot", capability: "payment-bot", reputation: 73, eta: "3 分钟" },
];

const state = {
  nodeId: `node_${crypto.randomUUID().slice(0, 8)}`,
  reputation: 72,
  agent: {
    name: "contract-auditor",
    capability: "solidity-audit",
    runtime: "local-ollama",
  },
  tasks: [],
  bids: [],
};

const elements = {
  nodeId: document.querySelector("#nodeId"),
  agentForm: document.querySelector("#agentForm"),
  agentName: document.querySelector("#agentName"),
  agentCapability: document.querySelector("#agentCapability"),
  agentRuntime: document.querySelector("#agentRuntime"),
  agentProfile: document.querySelector("#agentProfile"),
  taskForm: document.querySelector("#taskForm"),
  taskCapability: document.querySelector("#taskCapability"),
  taskBudget: document.querySelector("#taskBudget"),
  taskPrompt: document.querySelector("#taskPrompt"),
  taskList: document.querySelector("#taskList"),
  bidList: document.querySelector("#bidList"),
  simulateBtn: document.querySelector("#simulateBtn"),
  taskCount: document.querySelector("#taskCount"),
  repScore: document.querySelector("#repScore"),
  peerCount: document.querySelector("#peerCount"),
};

function signMessage(payload) {
  const encoded = JSON.stringify(payload);
  let hash = 0;
  for (let index = 0; index < encoded.length; index += 1) {
    hash = (hash << 5) - hash + encoded.charCodeAt(index);
    hash |= 0;
  }
  return `sig_${Math.abs(hash).toString(16).padStart(8, "0")}`;
}

function createTask() {
  const task = {
    id: `task_${String(state.tasks.length + 1).padStart(3, "0")}`,
    capability: elements.taskCapability.value,
    budget: elements.taskBudget.value,
    prompt: elements.taskPrompt.value.trim(),
    from: state.nodeId,
    createdAt: new Date().toLocaleTimeString("zh-CN", {
      hour: "2-digit",
      minute: "2-digit",
    }),
  };
  task.signature = signMessage(task);
  state.tasks.unshift(task);
  simulateBids(task);
}

function simulateBids(task = state.tasks[0]) {
  if (!task) return;

  const matching = peers.filter((peer) => peer.capability === task.capability);
  const fallback = peers.filter((peer) => peer.capability !== task.capability).slice(0, 1);
  const candidates = [...matching, ...fallback];

  const bids = candidates.map((peer, index) => ({
    id: `bid_${task.id}_${index}`,
    taskId: task.id,
    agent: peer.name,
    capability: peer.capability,
    reputation: peer.reputation,
    price: index === 0 ? task.budget : "2 USDC",
    eta: peer.eta,
    status: "pending",
    signature: signMessage({ taskId: task.id, agent: peer.name, price: task.budget }),
  }));

  state.bids = [...bids, ...state.bids.filter((bid) => bid.taskId !== task.id)];
  render();
}

function acceptBid(bidId) {
  state.bids = state.bids.map((bid) =>
    bid.id === bidId
      ? {
          ...bid,
          status: "done",
          result:
            "已完成模拟执行：发现 1 个 owner 权限风险、1 个无限授权提醒，未发现重入路径。",
        }
      : bid,
  );
  state.reputation += 1;
  render();
}

function renderAgent() {
  elements.agentProfile.innerHTML = `
    <strong>${state.agent.name}</strong>
    <p>能力：${capabilities[state.agent.capability]} · 运行时：${state.agent.runtime}</p>
    <div class="pill-row">
      <span class="pill">${state.nodeId}</span>
      <span class="pill">${signMessage(state.agent)}</span>
    </div>
  `;
}

function renderTasks() {
  if (state.tasks.length === 0) {
    elements.taskList.innerHTML = `<article class="card"><p>还没有任务。发布一个任务后，网络会模拟返回报价。</p></article>`;
    return;
  }

  elements.taskList.innerHTML = state.tasks
    .map(
      (task) => `
        <article class="card">
          <strong>${task.id} · ${capabilities[task.capability]}</strong>
          <p>${task.prompt}</p>
          <div class="pill-row">
            <span class="pill">${task.budget}</span>
            <span class="pill">${task.createdAt}</span>
            <span class="pill">${task.signature}</span>
          </div>
        </article>
      `,
    )
    .join("");
}

function renderBids() {
  if (state.bids.length === 0) {
    elements.bidList.innerHTML = `<article class="card"><p>暂无报价。可以点击“模拟报价”。</p></article>`;
    return;
  }

  elements.bidList.innerHTML = state.bids
    .map(
      (bid) => `
        <article class="card">
          <strong>${bid.agent} · ${bid.status === "done" ? "已执行" : "等待选择"}</strong>
          <p>报价 ${bid.price}，预计 ${bid.eta}，信誉 ${bid.reputation}。</p>
          ${bid.result ? `<p>${bid.result}</p>` : ""}
          <div class="pill-row">
            <span class="pill">${capabilities[bid.capability]}</span>
            <span class="pill">${bid.signature}</span>
          </div>
          ${
            bid.status === "pending"
              ? `<div class="bid-actions"><button class="small-button accept" type="button" data-bid="${bid.id}">接受并执行</button><button class="small-button" type="button">拉黑 peer</button></div>`
              : ""
          }
        </article>
      `,
    )
    .join("");
}

function renderMetrics() {
  elements.taskCount.textContent = state.tasks.length;
  elements.repScore.textContent = state.reputation;
  elements.peerCount.textContent = peers.length;
}

function render() {
  elements.nodeId.textContent = state.nodeId;
  renderAgent();
  renderTasks();
  renderBids();
  renderMetrics();
}

elements.agentForm.addEventListener("submit", (event) => {
  event.preventDefault();
  state.agent = {
    name: elements.agentName.value.trim() || "local-agent",
    capability: elements.agentCapability.value,
    runtime: elements.agentRuntime.value,
  };
  state.reputation += 1;
  render();
});

elements.taskForm.addEventListener("submit", (event) => {
  event.preventDefault();
  createTask();
  render();
});

elements.simulateBtn.addEventListener("click", () => simulateBids());

elements.bidList.addEventListener("click", (event) => {
  const button = event.target.closest("[data-bid]");
  if (!button) return;
  acceptBid(button.dataset.bid);
});

render();

