:root {
  color-scheme: light;
  --bg: #f5f7f2;
  --ink: #16201c;
  --muted: #64736f;
  --line: #d8dfd8;
  --surface: #ffffff;
  --surface-2: #eef3ed;
  --accent: #127767;
  --accent-2: #c2742d;
  --blue: #356f9f;
  --ok: #24a06f;
  --warn: #d48a27;
  --shadow: 0 18px 46px rgba(30, 42, 36, 0.12);
  --radius: 8px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family:
    Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    sans-serif;
  color: var(--ink);
  background:
    linear-gradient(120deg, rgba(18, 119, 103, 0.1), transparent 34%),
    linear-gradient(300deg, rgba(194, 116, 45, 0.1), transparent 32%),
    var(--bg);
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  border: 0;
}

.app {
  width: min(1380px, 100%);
  min-height: 100vh;
  margin: 0 auto;
  padding: 28px;
}

.topnav {
  min-height: 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 26px;
}

.brand,
.nav-tabs {
  display: flex;
  align-items: center;
  gap: 10px;
}

.brand-mark {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: var(--radius);
  color: #fff;
  background: var(--accent);
  font-size: 0.76rem;
  font-weight: 900;
}

.tab {
  min-height: 34px;
  padding: 0 12px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  color: var(--muted);
  background: transparent;
  cursor: pointer;
  font-weight: 800;
}

.tab.active {
  border-color: var(--line);
  color: var(--ink);
  background: rgba(255, 255, 255, 0.72);
}

.hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  gap: 24px;
  align-items: end;
  margin-bottom: 18px;
}

.eyebrow,
.label {
  margin: 0 0 8px;
  color: var(--accent);
  font-size: 0.78rem;
  font-weight: 850;
  letter-spacing: 0;
  text-transform: uppercase;
}

h1,
h2,
p {
  margin-top: 0;
}

h1 {
  max-width: 920px;
  margin-bottom: 16px;
  font-size: clamp(2.2rem, 4.5vw, 5rem);
  line-height: 0.98;
  letter-spacing: 0;
}

h2 {
  margin-bottom: 0;
  font-size: 1.08rem;
}

.summary {
  max-width: 760px;
  margin-bottom: 0;
  color: var(--muted);
  line-height: 1.7;
}

.wallet-card,
.panel,
.infra-strip {
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.86);
  box-shadow: var(--shadow);
  backdrop-filter: blur(16px);
  border-radius: var(--radius);
}

.wallet-card {
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 16px;
}

.wallet-card p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 0.88rem;
}

.status-dot {
  width: 13px;
  height: 13px;
  border-radius: 999px;
  background: var(--ok);
  box-shadow: 0 0 0 7px rgba(36, 160, 111, 0.14);
}

.infra-strip {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 10px;
  margin-bottom: 18px;
  padding: 10px;
}

.infra-strip div {
  min-height: 92px;
  position: relative;
  padding: 16px;
  border: 1px solid rgba(216, 223, 216, 0.8);
  border-radius: var(--radius);
  background: rgba(238, 243, 237, 0.72);
}

.infra-strip strong,
.infra-strip span,
.infra-strip small {
  display: block;
}

.infra-strip strong {
  padding-right: 48px;
}

.infra-strip small {
  position: absolute;
  top: 14px;
  right: 14px;
  color: var(--ok);
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
}

.infra-strip span {
  margin-top: 6px;
  color: var(--muted);
  font-size: 0.84rem;
}

.infra-dot {
  width: 8px;
  height: 8px;
  margin-bottom: 12px;
  border-radius: 999px;
  background: var(--ok);
}

.layout {
  display: grid;
  grid-template-columns: minmax(260px, 320px) minmax(0, 1fr) minmax(260px, 320px);
  gap: 18px;
}

.panel {
  padding: 20px;
}

.main-panel {
  min-width: 0;
}

.panel-header {
  margin-bottom: 18px;
}

.split {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.stack,
.task-form {
  display: grid;
  gap: 12px;
}

.task-form {
  grid-template-columns: 1fr 130px;
  align-items: end;
}

.wide {
  grid-column: 1 / -1;
}

label {
  display: grid;
  gap: 6px;
  color: var(--muted);
  font-size: 0.84rem;
  font-weight: 760;
}

input,
select,
textarea {
  width: 100%;
  border: 1px solid var(--line);
  background: #fff;
  color: var(--ink);
  padding: 11px 12px;
  outline: none;
}

textarea {
  min-height: 116px;
  resize: vertical;
}

input:focus,
select:focus,
textarea:focus {
  border-color: rgba(18, 119, 103, 0.6);
  box-shadow: 0 0 0 3px rgba(18, 119, 103, 0.12);
}

.primary-button,
.ghost-button,
.step-button {
  min-height: 42px;
  padding: 0 14px;
  border-radius: var(--radius);
  cursor: pointer;
  font-weight: 850;
}

.primary-button {
  color: #fff;
  background: var(--accent);
}

.ghost-button {
  border: 1px solid var(--line);
  color: var(--ink);
  background: var(--surface-2);
}

.step-button {
  min-height: 34px;
  color: #fff;
  background: var(--blue);
}

.primary-button:hover,
.ghost-button:hover,
.step-button:hover {
  filter: brightness(0.97);
}

.info-card,
.task-card,
.step {
  border: 1px solid var(--line);
  background: var(--surface-2);
  padding: 14px;
  border-radius: var(--radius);
}

.info-card {
  margin-top: 14px;
}

.info-card.compact {
  background: #fbfcfa;
}

.info-card strong,
.task-card strong,
.step strong {
  display: block;
  margin-bottom: 6px;
}

.info-card p,
.task-card p,
.step p {
  margin: 0;
