const STORAGE_KEY = "onenode.local.v1";

const defaultState = () => ({
  view: "task",
  wallet: {
    address: `0x${crypto.randomUUID().replaceAll("-", "").slice(0, 40)}`,
    balance: 50,
    escrow: 0,
    earned: 0,
  },
  reputation: 80,
  agent: {
    id: `agent_${crypto.randomUUID().slice(0, 8)}`,
    name: "research-node",
    skill: "项目尽调",
    runtime: "Ollama 本地模型",
  },
  tasks: [],
});

let state = loadState();

const elements = {
  tabs: [...document.querySelectorAll("[data-view]")],
  panels: [...document.querySelectorAll("[data-panel]")],
  walletAddress: document.querySelector("#walletAddress"),
  walletBalance: document.querySelector("#walletBalance"),
  escrowBalance: document.querySelector("#escrowBalance"),
  earnedBalance: document.querySelector("#earnedBalance"),
  reputationScore: document.querySelector("#reputationScore"),
  agentForm: document.querySelector("#agentForm"),
  agentName: document.querySelector("#agentName"),
  agentSkill: document.querySelector("#agentSkill"),
  agentRuntime: document.querySelector("#agentRuntime"),
  agentCard: document.querySelector("#agentCard"),
  taskForm: document.querySelector("#taskForm"),
  taskType: document.querySelector("#taskType"),
  taskBudget: document.querySelector("#taskBudget"),
  taskPrompt: document.querySelector("#taskPrompt"),
  taskList: document.querySelector("#taskList"),
  taskSummary: document.querySelector("#taskSummary"),
  activeTask: document.querySelector("#activeTask"),
  historyList: document.querySelector("#historyList"),
  resetBtn: document.querySelector("#resetBtn"),
  seedBtn: document.querySelector("#seedBtn"),
};

const statusLabel = {
  open: "待接单",
  accepted: "已接单",
  running: "执行中",
  submitted: "待确认",
  paid: "已结算",
};

function loadState() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
    return saved ? { ...defaultState(), ...saved } : defaultState();
  } catch {
    return defaultState();
  }
}

function saveState() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

function shortAddress(address) {
  return `${address.slice(0, 6)}...${address.slice(-4)}`;
}

function money(value) {
  return Number(value).toFixed(2);
}

function hashPayload(payload) {
  const text = JSON.stringify(payload);
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash += (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24);
  }
  return `0x${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

function sign(payload) {
  return `sig_${hashPayload({ payload, agent: state.agent.id }).slice(2)}`;
}

function setView(view) {
  state.view = view;
  saveState();
  render();
}

function createTask() {
  const budget = Math.max(Number.parseFloat(elements.taskBudget.value) || 0, 0);
  const prompt = elements.taskPrompt.value.trim();
  if (!prompt || budget <= 0 || budget > state.wallet.balance) return;

  const task = {
    id: `task_${String(Date.now()).slice(-6)}`,
    type: elements.taskType.value,
    prompt,
    budget,
    status: "open",
    createdAt: new Date().toLocaleString("zh-CN"),
    inputHash: "",
    publisherSignature: "",
  };
  task.inputHash = hashPayload(task);
  task.publisherSignature = sign({ task, role: "publisher" });

  state.wallet.balance -= budget;
  state.wallet.escrow += budget;
  state.tasks.unshift(task);
  saveState();
  render();
}

function seedTasks() {
  const examples = [
    ["合约初审", "检查 ERC-20 合约 owner 权限、无限授权、暂停函数和升级代理风险。", 8],
    ["链上分析", "分析一个地址过去 30 天资金流、主要交互协议和异常转账。", 4],
    ["DAO 周报", "总结治理论坛本周提案、争议点、投票风险和建议行动。", 3],
  ];

  examples.forEach(([type, prompt, budget]) => {
    if (budget > state.wallet.balance) return;
    elements.taskType.value = type;
    elements.taskPrompt.value = prompt;
    elements.taskBudget.value = String(budget);
    createTask();
  });
}

function updateTask(id, next) {
  state.tasks = state.tasks.map((task) => (task.id === id ? { ...task, ...next } : task));
}

function acceptTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "open") return;
  updateTask(id, {
    status: "accepted",
    worker: state.agent.name,
    acceptSignature: sign({ taskId: id, action: "accept" }),
  });
  saveState();
  setView("agent");
}

function runTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "accepted") return;
  updateTask(id, {
    status: "running",
    executionLog: `${state.agent.runtime} 已完成 ${task.type} 的本地模拟执行。`,
  });
  saveState();
  render();
}

function submitTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "running") return;
  const result = buildResult(task);
  const resultHash = hashPayload({ taskId: id, result, agent: state.agent.id });
  updateTask(id, {
    status: "submitted",
    result,
    resultUri: `r2-ipfs://${id}.json`,
    resultHash,
    resultSignature: sign({ taskId: id, resultHash }),
  });
  saveState();
  render();
}

function payTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "submitted") return;
  updateTask(id, {
    status: "paid",
    paidAt: new Date().toLocaleString("zh-CN"),
    settlementHash: hashPayload({ taskId: id, paid: task.budget }),
  });
  state.wallet.escrow -= task.budget;
  state.wallet.earned += task.budget;
  state.reputation += 3;
  saveState();
  render();
}

function refundTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status === "paid") return;
  updateTask(id, { status: "refunded" });
  state.wallet.escrow -= task.budget;
  state.wallet.balance += task.budget;
  state.reputation = Math.max(0, state.reputation - 1);
  saveState();
  render();
}

function buildResult(task) {
  const templates = {
    项目尽调: "交付摘要：产品定位清楚，代币权限和流动性集中是主要风险，建议继续跟踪团队执行与解锁时间表。",
    合约初审: "交付摘要：发现 owner 权限集中、approve 使用需提示，未发现明显重入路径，建议补充事件日志和暂停策略。",
    链上分析: "交付摘要：资金主要流向 DEX 与稳定币池，存在 2 笔异常大额转出，建议加入地址监控。",
    "DAO 周报": "交付摘要：本周核心争议集中在预算分配和贡献者激励，建议拆分投票并补充执行里程碑。",
  };
  return templates[task.type] || "交付摘要：任务已完成，结果已生成。";
}

function resetAll() {
  localStorage.removeItem(STORAGE_KEY);
  state = defaultState();
  render();
}

function render() {
  renderNavigation();
  renderForms();
  renderAgent();
  renderMetrics();
  renderTasks();
  renderActiveTask();
  renderHistory();
}

function renderNavigation() {
  elements.tabs.forEach((tab) => tab.classList.toggle("active", tab.dataset.view === state.view));
  elements.panels.forEach((panel) => panel.classList.toggle("hidden", panel.dataset.panel !== state.view));
}

function renderForms() {
  elements.agentName.value = state.agent.name;
  elements.agentSkill.value = state.agent.skill;
  elements.agentRuntime.value = state.agent.runtime;
}

function renderAgent() {
  elements.agentCard.innerHTML = `
    <strong>${state.agent.name}</strong>
    <p>${state.agent.skill} · ${state.agent.runtime}</p>
    <div class="pill-row">
      <span class="pill">${state.agent.id}</span>
      <span class="pill">ERC-8004 ready</span>
    </div>
  `;
}

function renderMetrics() {
  const escrow = state.tasks
    .filter((task) => !["paid", "refunded"].includes(task.status))
    .reduce((sum, task) => sum + task.budget, 0);
  state.wallet.escrow = escrow;
  elements.walletAddress.textContent = shortAddress(state.wallet.address);
  elements.walletBalance.textContent = money(state.wallet.balance);
  elements.escrowBalance.textContent = money(state.wallet.escrow);
  elements.earnedBalance.textContent = money(state.wallet.earned);
  elements.reputationScore.textContent = state.reputation;
}

function renderTasks() {
  const activeTasks = state.tasks.filter((task) => task.status !== "paid" && task.status !== "refunded");
  elements.taskSummary.textContent = `${activeTasks.length} 个进行中 / ${state.tasks.length} 个全部`;
  elements.taskList.innerHTML =
    activeTasks.map(renderTaskCard).join("") ||
    `<article class="task-card"><strong>暂无任务</strong><p>发布任务后会进入本地 Escrow，并出现在这里。</p></article>`;
}

function renderActiveTask() {
  const workable = state.tasks.find((task) => ["accepted", "running"].includes(task.status));
  const waiting = state.tasks.find((task) => task.status === "submitted");
  const task = workable || waiting || state.tasks.find((item) => item.status === "open");
  elements.activeTask.innerHTML = task
    ? renderTaskCard(task, true)
    : `<article class="task-card"><strong>暂无可处理任务</strong><p>去任务页发布或接单一个任务。</p></article>`;
}

function renderHistory() {
  const history = state.tasks.filter((task) => ["paid", "refunded", "submitted"].includes(task.status));
  elements.historyList.innerHTML =
    history.map((task) => renderTaskCard(task, true)).join("") ||
    `<article class="task-card"><strong>暂无历史</strong><p>结算后的任务会在这里沉淀为收益和信誉记录。</p></article>`;
}

function renderTaskCard(task, expanded = false) {
  const actions = actionButtons(task);
  const result = expanded && task.result
    ? `<p>${task.result}</p>
       <div class="pill-row">
         <span class="pill">${task.resultUri}</span>
         <span class="pill">${task.resultHash}</span>
         <span class="pill">${task.resultSignature}</span>
       </div>`
    : "";
  const settlement = task.settlementHash ? `<span class="pill">${task.settlementHash}</span>` : "";

  return `
    <article class="task-card status-${task.status}">
      <div class="task-card-head">
        <strong>${task.id} · ${task.type}</strong>
        <span class="status-badge">${statusLabel[task.status] || task.status}</span>
      </div>
      <p>${task.prompt}</p>
      ${result}
      <div class="pill-row">
        <span class="pill">${task.budget} USDC</span>
        <span class="pill">${task.inputHash}</span>
        <span class="pill">${task.publisherSignature}</span>
        ${settlement}
      </div>
      ${actions ? `<div class="action-row">${actions}</div>` : ""}
    </article>
  `;
}

function actionButtons(task) {
  if (task.status === "open") {
    return `<button class="step-button" type="button" data-action="accept" data-id="${task.id}">Agent 接单</button>
      <button class="ghost-button" type="button" data-action="refund" data-id="${task.id}">退款</button>`;
  }
  if (task.status === "accepted") {
    return `<button class="step-button" type="button" data-action="run" data-id="${task.id}">运行 Agent</button>`;
  }
  if (task.status === "running") {
    return `<button class="step-button" type="button" data-action="submit" data-id="${task.id}">提交结果</button>`;
  }
  if (task.status === "submitted") {
    return `<button class="step-button" type="button" data-action="pay" data-id="${task.id}">确认付款</button>
      <button class="ghost-button" type="button" data-action="refund" data-id="${task.id}">退回托管</button>`;
  }
  return "";
}

elements.tabs.forEach((tab) => tab.addEventListener("click", () => setView(tab.dataset.view)));

elements.agentForm.addEventListener("submit", (event) => {
  event.preventDefault();
  state.agent = {
    ...state.agent,
    name: elements.agentName.value.trim() || "local-agent",
    skill: elements.agentSkill.value,
    runtime: elements.agentRuntime.value,
  };
  saveState();
  render();
});

elements.taskForm.addEventListener("submit", (event) => {
  event.preventDefault();
  createTask();
});

document.body.addEventListener("click", (event) => {
  const button = event.target.closest("[data-action]");
  if (!button) return;
  const { action, id } = button.dataset;
  if (action === "accept") acceptTask(id);
  if (action === "run") runTask(id);
  if (action === "submit") submitTask(id);
  if (action === "pay") payTask(id);
  if (action === "refund") refundTask(id);
});

elements.seedBtn.addEventListener("click", seedTasks);
elements.resetBtn.addEventListener("click", resetAll);

render();

