    executionLog: `${state.agent.runtime} 已完成 ${task.type} 的本地模拟执行。`,
  });
  saveState();
  render();
}

function submitTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "running") return;
  const result = buildResult(task);
  const resultHash = hashPayload({ taskId: id, result, agent: state.agent.id });
  updateTask(id, {
    status: "submitted",
