function acceptTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "open") return;
  updateTask(id, {
    status: "accepted",
    worker: state.agent.name,
    acceptSignature: sign({ taskId: id, action: "accept" }),
  });
  saveState();
  setView("agent");
}

async function runTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "accepted") return;
  updateTask(id, {
    status: "running",
    executionLog: `${state.agent.runtime} 正在执行 ${task.type}。`,
  });
  saveState();
  render();

  const result = await generateWithAgent(task);
  const resultHash = hashPayload({ taskId: id, result, agent: state.agent.id });
  updateTask(id, {
    status: "submitted",
    result,
    resultUri: `r2-ipfs://${id}.json`,
    resultHash,
    resultSignature: sign({ taskId: id, resultHash }),
  });
  saveState();
  render();
}

function submitTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "running") return;
  const result = buildResult(task);
  const resultHash = hashPayload({ taskId: id, result, agent: state.agent.id });
  updateTask(id, {
    status: "submitted",
    result,
    resultUri: `r2-ipfs://${id}.json`,
    resultHash,
    resultSignature: sign({ taskId: id, resultHash }),
  });
  saveState();
  render();
}

async function generateWithAgent(task) {
  if (state.agent.runtime === "Ollama 本地模型") {
    try {
      return await callOllama(task);
    } catch (error) {
      state.agent.modelStatus = `Ollama 调用失败，已回退模拟结果：${error.message}`;
      return buildResult(task);
    }
  }
  if (state.agent.runtime === "OpenAI compatible API") {
    try {
      return await callOnlineApi(task);
    } catch (error) {
      state.agent.modelStatus = `线上 API 调用失败，已回退模拟结果：${error.message}`;
      return buildResult(task);
    }
  }
  return buildResult(task);
}

async function callOllama(task) {
  const endpoint = state.agent.ollamaEndpoint.replace(/\/$/, "");
  const response = await fetch(`${endpoint}/api/generate`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      model: state.agent.ollamaModel,
      stream: false,
      prompt: [
        "你是 OneNode 上的 Web3 投资与收益分析 Agent。请用中文输出决策型报告。",
        `任务类型：${task.type}`,
        `任务内容：${task.prompt}`,
        "输出结构：结论、机会评分(1-10)、风险评分(1-10)、建议操作、关键原因、风险清单、需要继续跟踪的数据。不要承诺收益。",
      ].join("\n"),
    }),
  });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const data = await response.json();
  const text = data.response?.trim();
  if (!text) throw new Error("模型没有返回内容");
  state.agent.modelStatus = `已连接 ${state.agent.ollamaModel}`;
  return text;
}

async function testLocalModel() {
  state.agent = {
    ...state.agent,
    ollamaEndpoint: elements.ollamaEndpoint.value.trim() || "http://127.0.0.1:11434",
    ollamaModel: elements.ollamaModel.value.trim() || "llama3.2",
  };
  state.agent.modelStatus = "测试中...";
  saveState();
  render();

  try {
    const endpoint = state.agent.ollamaEndpoint.replace(/\/$/, "");
    const response = await fetch(`${endpoint}/api/tags`);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    const models = data.models?.map((model) => model.name) || [];
    const found = models.some((name) => name === state.agent.ollamaModel || name.startsWith(`${state.agent.ollamaModel}:`));
    state.agent.modelStatus = found
      ? `已连接 ${state.agent.ollamaModel}`
      : `已连接 Ollama，但未找到 ${state.agent.ollamaModel}`;
  } catch (error) {
    state.agent.modelStatus = `连接失败：${error.message}`;
  }
  saveState();
  render();
}

