    risk: "费用开关、监管、竞争 DEX 和代币价值捕获不确定。",
    taskType: "项目快评",
  },
  {
    symbol: "SKY",
    name: "Sky / Maker",
    category: "稳定币 / CDP",
    why: "稳定币、抵押债仓和链上收益体系有长期历史，是 DeFi 核心组件。",
    risk: "抵押品结构、治理、稳定币竞争和监管压力。",
    taskType: "稳定币收益扫描",
  },
  {
    symbol: "ARB",
    name: "Arbitrum",
    category: "Ethereum L2",
    why: "以太坊 L2 重要生态，DeFi 和应用部署丰富，适合作为收益机会来源。",
    risk: "L2 竞争激烈，代币价值捕获和排序器收入分配仍需观察。",
    taskType: "项目快评",
  },
  {
    symbol: "BASE",
    name: "Base Ecosystem",
    category: "Ethereum L2 生态",
    why: "Coinbase 支持的 L2，适合稳定币支付、消费者应用和 Agent 支付场景。",
    risk: "Base 暂无原生代币，更多适合研究生态项目而非直接买入 Base。",
    taskType: "项目快评",
  },
];

const baseChain = {
  chainId: "0x2105",
  chainName: "Base",
  nativeCurrency: { name: "Ether", symbol: "ETH", decimals: 18 },
  rpcUrls: ["https://mainnet.base.org"],
  blockExplorerUrls: ["https://basescan.org"],
};

function loadState() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
    if (!saved) return defaultState();
    const defaults = defaultState();
    return {
      ...defaults,
      ...saved,
      wallet: { ...defaults.wallet, ...saved.wallet },
      agent: { ...defaults.agent, ...saved.agent },
      tasks: saved.tasks || [],
    };
  } catch {
    return defaultState();
  }
}

function saveState() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

function hasInjectedWallet() {
  return typeof window.ethereum !== "undefined";
}

function shortAddress(address) {
  return `${address.slice(0, 6)}...${address.slice(-4)}`;
}

function money(value) {
  return Number(value).toFixed(2);
}

function hashPayload(payload) {
  const text = JSON.stringify(payload);
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash += (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24);
  }
  return `0x${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

function sign(payload) {
  return `sig_${hashPayload({ payload, agent: state.agent.id }).slice(2)}`;
}

function setView(view) {
  state.view = view;
  saveState();
  render();
}

async function connectWallet() {
  if (!hasInjectedWallet()) {
    state.wallet.mode = "local";
    state.wallet.error = "未检测到浏览器钱包。请用安装了 MetaMask/Rabby/Coinbase Wallet 的浏览器，并优先通过 localhost 打开页面。";
    saveState();
    render();
    return;
  }

  try {
    const accounts = await window.ethereum.request({ method: "eth_requestAccounts" });
    const chainId = await window.ethereum.request({ method: "eth_chainId" });
    state.wallet.connectedAddress = accounts[0] || "";
    state.wallet.chainId = chainId;
    state.wallet.mode = state.wallet.connectedAddress ? "connected" : "local";
    state.wallet.error = "";
    saveState();
    render();
  } catch {
    state.wallet.mode = "local";
    state.wallet.error = "钱包连接被取消或浏览器阻止了连接请求。";
    saveState();
    render();
  }
}

async function switchToBase() {
  if (!hasInjectedWallet()) return;
  try {
    await window.ethereum.request({
      method: "wallet_switchEthereumChain",
      params: [{ chainId: baseChain.chainId }],
    });
  } catch (error) {
    if (error.code === 4902) {
      await window.ethereum.request({
        method: "wallet_addEthereumChain",
        params: [baseChain],
      });
    }
  }
  state.wallet.chainId = await window.ethereum.request({ method: "eth_chainId" });
  saveState();
  render();
}

function createTask() {
  const budget = Math.max(Number.parseFloat(elements.taskBudget.value) || 0, 0);
  const prompt = elements.taskPrompt.value.trim();
  if (!prompt || budget <= 0 || budget > state.wallet.balance) return;

  const task = {
    id: `task_${String(Date.now()).slice(-6)}`,
    type: elements.taskType.value,
    prompt,
    budget,
    status: "open",
    createdAt: new Date().toLocaleString("zh-CN"),
    inputHash: "",
    publisherSignature: "",
  };
  task.inputHash = hashPayload(task);
  task.publisherSignature = sign({ task, role: "publisher" });

  state.wallet.balance -= budget;
  state.wallet.escrow += budget;
  state.tasks.unshift(task);
  saveState();
  render();
}

function seedTasks() {
  const examples = [
    ["项目快评", "快速判断一个新 L2 项目是否值得跟踪：产品定位、融资、代币风险、竞品、当前热度。", 5],
    ["Token 风险扫描", "扫描一个 Base 链 Token：持仓集中度、流动性、owner 权限、税费/黑名单风险。", 8],
    ["稳定币收益扫描", "寻找 1 万 USDC、低到中风险、周期 30 天的稳定币收益机会，并列出退出条件。", 6],
  ];

  examples.forEach(([type, prompt, budget]) => {
    if (budget > state.wallet.balance) return;
    elements.taskType.value = type;
    elements.taskPrompt.value = prompt;
    elements.taskBudget.value = String(budget);
    createTask();
  });
}

function updateTask(id, next) {
  state.tasks = state.tasks.map((task) => (task.id === id ? { ...task, ...next } : task));
}

function acceptTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "open") return;
  updateTask(id, {
    status: "accepted",
    worker: state.agent.name,
    acceptSignature: sign({ taskId: id, action: "accept" }),
  });
  saveState();
  setView("agent");
}

async function runTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "accepted") return;
  updateTask(id, {
    status: "running",
    executionLog: `${state.agent.runtime} 正在执行 ${task.type}。`,
  });
  saveState();
  render();

  const result = await generateWithAgent(task);
  const resultHash = hashPayload({ taskId: id, result, agent: state.agent.id });
  updateTask(id, {
    status: "submitted",
    result,
    resultUri: `r2-ipfs://${id}.json`,
    resultHash,
    resultSignature: sign({ taskId: id, resultHash }),
  });
  saveState();
  render();
}

function submitTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "running") return;
  const result = buildResult(task);
  const resultHash = hashPayload({ taskId: id, result, agent: state.agent.id });
  updateTask(id, {
    status: "submitted",
    result,
    resultUri: `r2-ipfs://${id}.json`,
    resultHash,
    resultSignature: sign({ taskId: id, resultHash }),
  });
  saveState();
  render();
}

async function generateWithAgent(task) {
  try {
    return await callOnlineApi(task);
  } catch (error) {
    state.agent.modelStatus = `线上 Agent 调用失败，已回退模拟结果：${error.message}`;
    return buildResult(task);
  }
}

async function callOnlineApi(task) {
  const baseUrl = state.agent.onlineApiBase.replace(/\/$/, "");
  if (!state.agent.onlineApiKey) throw new Error("缺少 API Key");
  const response = await fetch(`${baseUrl}/chat/completions`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${state.agent.onlineApiKey}`,
    },
    body: JSON.stringify({
      model: state.agent.onlineModel,
      messages: [
        {
          role: "system",
          content:
            "你是 OneNode 上的 Web3 投资与收益分析 Agent。请输出决策型报告，包含结论、机会评分、风险评分、建议操作、关键原因、风险清单、需要继续跟踪的数据。不要承诺收益。",
        },
        {
          role: "user",
          content: `任务类型：${task.type}\n任务内容：${task.prompt}`,
        },
      ],
      temperature: 0.3,
    }),
  });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const data = await response.json();
  const text = data.choices?.[0]?.message?.content?.trim();
  if (!text) throw new Error("模型没有返回内容");
  state.agent.modelStatus = `已连接 ${state.agent.onlineModel}`;
  return text;
}

async function testOnlineApi() {
  state.agent = readAgentForm();
  state.agent.modelStatus = "测试线上 API 中...";
  saveState();
  render();

  try {
    const text = await callOnlineApi({
      type: "连接测试",
      prompt: "请回复一句 OneNode 线上模型连接成功。",
    });
    state.agent.modelStatus = text ? `线上 API 可用：${state.agent.onlineModel}` : "线上 API 无返回";
  } catch (error) {
    state.agent.modelStatus = `线上 API 连接失败：${error.message}`;
  }
  saveState();
  render();
}

function payTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "submitted") return;
  updateTask(id, {
    status: "paid",
    paidAt: new Date().toLocaleString("zh-CN"),
    settlementHash: hashPayload({ taskId: id, paid: task.budget }),
  });
  state.wallet.escrow -= task.budget;
  state.wallet.earned += task.budget;
  state.reputation += 3;
  saveState();
  render();
}

function refundTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status === "paid") return;
  updateTask(id, { status: "refunded" });
  state.wallet.escrow -= task.budget;
  state.wallet.balance += task.budget;
  state.reputation = Math.max(0, state.reputation - 1);
  saveState();
  render();
}

function buildResult(task) {
  const templates = {
    项目快评:
      "结论：继续跟踪。机会评分 7/10，风险评分 6/10。建议操作：先观察，不建议重仓。关键原因：叙事清晰但链上数据不足；主要风险是代币权限、流动性集中和解锁不透明。",
    项目深度尽调:
      "结论：需要进一步尽调。机会评分 6/10，风险评分 7/10。建议操作：补充团队、融资、代币分布和竞品数据后再判断。重点跟踪 TVL、活跃地址、收入和解锁表。",
    "Token 风险扫描":
      "结论：谨慎参与。机会评分 5/10，风险评分 8/10。建议操作：小仓位或不参与。风险包括持仓集中、流动性较薄、owner 权限未完全放弃和潜在黑名单/税费逻辑。",
    稳定币收益扫描:
      "结论：可关注低到中风险池。机会评分 6/10，风险评分 4/10。建议操作：优先 TVL 高、APY 来源清晰、可快速退出的稳定币池；退出信号包括 APY 异常飙升、TVL 快速流出、稳定币脱锚。",
    收益池风险分析:
      "结论：需要控制仓位。机会评分 6/10，风险评分 6/10。建议操作：确认 APY 来源、审计状态、池子 TVL、资产脱锚风险和合约权限后再进入。",
    "空投/积分机会分析":
      "结论：适合低成本参与。机会评分 7/10，风险评分 5/10。建议操作：优先完成低成本链上交互，避免高滑点、高 Gas 和需要长期锁仓的任务。",
  };
  return templates[task.type] || "结论：需要补充数据。机会评分 5/10，风险评分 5/10。建议操作：先观察，不做高风险操作。";
}

function resetAll() {
  localStorage.removeItem(STORAGE_KEY);
  state = defaultState();
  render();
}

function render() {
  renderNavigation();
  renderForms();
  renderAgent();
  renderMetrics();
  renderTasks();
  renderWatchlist();
  renderActiveTask();
  renderHistory();
}

function renderNavigation() {
  elements.tabs.forEach((tab) => tab.classList.toggle("active", tab.dataset.view === state.view));
  elements.panels.forEach((panel) => panel.classList.toggle("hidden", panel.dataset.panel !== state.view));
}

function renderForms() {
  elements.agentName.value = state.agent.name;
  elements.agentSkill.value = state.agent.skill;
  elements.onlineApiBase.value = state.agent.onlineApiBase;
  elements.onlineModel.value = state.agent.onlineModel;
  elements.onlineApiKey.value = state.agent.onlineApiKey;
}

function renderAgent() {
  elements.agentCard.innerHTML = `
    <strong>${state.agent.name}</strong>
    <p>${state.agent.skill} · 线上 Agent API</p>
    <div class="pill-row">
      <span class="pill">${state.agent.id}</span>
      <span class="pill">ERC-8004 ready</span>
      <span class="pill">${state.agent.modelStatus}</span>
    </div>
  `;
}

function renderMetrics() {
  const escrow = state.tasks
    .filter((task) => !["paid", "refunded"].includes(task.status))
    .reduce((sum, task) => sum + task.budget, 0);
  state.wallet.escrow = escrow;
  const connected = state.wallet.mode === "connected" && state.wallet.connectedAddress;
  const address = connected ? state.wallet.connectedAddress : state.wallet.address;
  const onBase = state.wallet.chainId === baseChain.chainId;
  elements.walletAddress.textContent = shortAddress(address);
  elements.walletStatus.textContent = state.wallet.error
    ? state.wallet.error
    : connected
      ? `${onBase ? "Base" : `Chain ${state.wallet.chainId}`} · 钱包已连接 · 本地模拟结算`
      : "Local Wallet · 模拟余额 · 未连接真实钱包";
  elements.connectWalletBtn.textContent = connected ? (onBase ? "已连接" : "切到 Base") : "连接钱包";
  elements.walletBalance.textContent = money(state.wallet.balance);
  elements.escrowBalance.textContent = money(state.wallet.escrow);
  elements.earnedBalance.textContent = money(state.wallet.earned);
  elements.reputationScore.textContent = state.reputation;
}

function renderTasks() {
  const activeTasks = state.tasks.filter((task) => task.status !== "paid" && task.status !== "refunded");
  elements.taskSummary.textContent = `${activeTasks.length} 个进行中 / ${state.tasks.length} 个全部`;
  elements.taskList.innerHTML =
    activeTasks.map(renderTaskCard).join("") ||
    `<article class="task-card"><strong>暂无任务</strong><p>发布任务后会进入本地 Escrow，并出现在这里。</p></article>`;
}

function renderWatchlist() {
  elements.watchlist.innerHTML = reliableWatchlist
    .map(
      (item) => `
        <article class="watch-card">
          <header>
            <div>
              <h3>${item.symbol} · ${item.name}</h3>
              <span class="watch-tag">${item.category}</span>
            </div>
          </header>
          <p>${item.why}</p>
          <p>主要风险：${item.risk}</p>
          <div class="watch-actions">
            <button class="ghost-button" type="button" data-watch="${item.symbol}">生成分析任务</button>
          </div>
        </article>
      `,
    )
    .join("");
}

function renderActiveTask() {
  const workable = state.tasks.find((task) => ["accepted", "running"].includes(task.status));
  const waiting = state.tasks.find((task) => task.status === "submitted");
  const task = workable || waiting || state.tasks.find((item) => item.status === "open");
  elements.activeTask.innerHTML = task
    ? renderTaskCard(task, true)
    : `<article class="task-card"><strong>暂无可处理任务</strong><p>去任务页发布或接单一个任务。</p></article>`;
}

function renderHistory() {
  const history = state.tasks.filter((task) => ["paid", "refunded", "submitted"].includes(task.status));
  elements.historyList.innerHTML =
    history.map((task) => renderTaskCard(task, true)).join("") ||
    `<article class="task-card"><strong>暂无历史</strong><p>结算后的任务会在这里沉淀为收益和信誉记录。</p></article>`;
}

function renderTaskCard(task, expanded = false) {
  const actions = actionButtons(task);
  const result = expanded && task.result
    ? `<p>${task.result}</p>
       <div class="pill-row">
         <span class="pill">${task.resultUri}</span>
         <span class="pill">${task.resultHash}</span>
         <span class="pill">${task.resultSignature}</span>
       </div>`
    : "";
  const settlement = task.settlementHash ? `<span class="pill">${task.settlementHash}</span>` : "";

  return `
    <article class="task-card status-${task.status}">
      <div class="task-card-head">
        <strong>${task.id} · ${task.type}</strong>
        <span class="status-badge">${statusLabel[task.status] || task.status}</span>
      </div>
      <p>${task.prompt}</p>
      ${result}
      <div class="pill-row">
        <span class="pill">${task.budget} USDC</span>
        <span class="pill">${task.inputHash}</span>
        <span class="pill">${task.publisherSignature}</span>
        ${settlement}
      </div>
      ${actions ? `<div class="action-row">${actions}</div>` : ""}
    </article>
  `;
}

function actionButtons(task) {
  if (task.status === "open") {
    return `<button class="step-button" type="button" data-action="accept" data-id="${task.id}">Agent 接单</button>
      <button class="ghost-button" type="button" data-action="refund" data-id="${task.id}">退款</button>`;
  }
  if (task.status === "accepted") {
    return `<button class="step-button" type="button" data-action="run" data-id="${task.id}">运行并提交结果</button>`;
  }
  if (task.status === "running") {
    return `<button class="step-button" type="button" data-action="submit" data-id="${task.id}">提交结果</button>`;
  }
  if (task.status === "submitted") {
    return `<button class="step-button" type="button" data-action="pay" data-id="${task.id}">确认付款</button>
      <button class="ghost-button" type="button" data-action="refund" data-id="${task.id}">退回托管</button>`;
  }
  return "";
}

elements.tabs.forEach((tab) => tab.addEventListener("click", () => setView(tab.dataset.view)));
elements.templateButtons.forEach((button) =>
  button.addEventListener("click", () => {
    const template = demandTemplates[button.dataset.template];
    if (!template) return;
    elements.taskType.value = template.type;
    elements.taskBudget.value = template.budget;
    elements.taskPrompt.value = template.prompt;
  }),
);

elements.agentForm.addEventListener("submit", (event) => {
  event.preventDefault();
  state.agent = readAgentForm();
  saveState();
  render();
});

function readAgentForm() {
  return {
    ...state.agent,
    name: elements.agentName.value.trim() || "local-agent",
    skill: elements.agentSkill.value,
    runtime: "Online Agent API",
    onlineApiBase: elements.onlineApiBase.value.trim() || "https://api.openai.com/v1",
    onlineModel: elements.onlineModel.value.trim() || "gpt-4.1-mini",
    onlineApiKey: elements.onlineApiKey.value.trim(),
  };
}

elements.taskForm.addEventListener("submit", (event) => {
  event.preventDefault();
  createTask();
});

document.body.addEventListener("click", (event) => {
  const watchButton = event.target.closest("[data-watch]");
  if (watchButton) {
    const item = reliableWatchlist.find((entry) => entry.symbol === watchButton.dataset.watch);
    if (!item) return;
    elements.taskType.value = item.taskType;
    elements.taskBudget.value = item.taskType === "项目深度尽调" ? "15" : "5";
    elements.taskPrompt.value = `分析 ${item.symbol} / ${item.name}：判断是否值得关注，说明机会评分、风险评分、主要催化剂、关键风险、建议操作和需要继续跟踪的数据。`;
    window.scrollTo({ top: 0, behavior: "smooth" });
    return;
  }

  const button = event.target.closest("[data-action]");
  if (!button) return;
  const { action, id } = button.dataset;
  if (action === "accept") acceptTask(id);
  if (action === "run") runTask(id);
  if (action === "submit") submitTask(id);
  if (action === "pay") payTask(id);
  if (action === "refund") refundTask(id);
});

elements.seedBtn.addEventListener("click", seedTasks);
elements.resetBtn.addEventListener("click", resetAll);
elements.testOnlineApiBtn.addEventListener("click", testOnlineApi);
elements.connectWalletBtn.addEventListener("click", () => {
  if (state.wallet.mode === "connected" && state.wallet.chainId !== baseChain.chainId) {
    switchToBase();
    return;
  }
  connectWallet();
});

if (hasInjectedWallet()) {
  window.ethereum.on?.("accountsChanged", (accounts) => {
    state.wallet.connectedAddress = accounts[0] || "";
    state.wallet.mode = accounts[0] ? "connected" : "local";
    saveState();
    render();
  });
  window.ethereum.on?.("chainChanged", (chainId) => {
    state.wallet.chainId = chainId;
    saveState();
    render();
  });
}

render();

