    return normalizeState({
      ...defaults,
      ...saved,
      wallet: { ...defaults.wallet, ...saved.wallet },
      agent: { ...defaults.agent, ...saved.agent },
      tasks: saved.tasks || [],
    });
  } catch {
    return defaultState();
  }
}

function normalizeState(nextState) {
  nextState.agent.skill = skillMap[nextState.agent.skill] || nextState.agent.skill || "Investment opportunity analysis";
  nextState.agent.runtime = "Online Agent API";
  nextState.agent.modelStatus = translateStatus(nextState.agent.modelStatus);
  nextState.wallet.error = translateWalletMessage(nextState.wallet.error);
  nextState.tasks = nextState.tasks.map((task) => ({
    ...task,
    type: typeMap[task.type] || task.type,
    prompt: translatePrompt(task.prompt),
    result: translateResult(task.result),
  }));
  return nextState;
}

function translateStatus(status) {
  if (!status || status === "未测试") return "Not tested";
  if (status.includes("线上 API 可用")) return status.replace("线上 API 可用", "Online API ready");
  if (status.includes("线上 API 连接失败")) return status.replace("线上 API 连接失败", "Online API failed");
  if (status.includes("已连接")) return status.replace("已连接", "Connected");
  return status;
}

function translateWalletMessage(message) {
  if (!message) return "";
  if (message.includes("未检测到浏览器钱包")) {
    return "No browser wallet detected. Use a browser with MetaMask, Rabby, or Coinbase Wallet, preferably through localhost.";
  }
  if (message.includes("钱包连接被取消")) return "Wallet connection was cancelled or blocked by the browser.";
  return message;
}

function translatePrompt(prompt) {
  const promptMap = {
    "分析一个新 Web3 项目：判断是否值得关注，说明机会等级、风险等级、代币风险、竞品和建议操作。":
