  border-color: transparent;
  color: #000;
  background: rgba(255, 255, 255, 0.92);
}

.hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  gap: 30px;
  align-items: center;
  min-height: 430px;
  margin-bottom: 24px;
  padding: 56px clamp(22px, 5vw, 72px);
  border-radius: var(--radius);
