  line-height: 0.94;
  font-weight: 800;
  letter-spacing: 0;
}

h2 {
  margin-bottom: 0;
  font-size: 1.16rem;
  font-weight: 760;
}

.summary {
  max-width: 720px;
  margin-bottom: 0;
  color: var(--muted);
  font-size: clamp(1.05rem, 1.5vw, 1.34rem);
  line-height: 1.45;
}

.wallet-card,
.panel,
.infra-strip {
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.92);
  box-shadow: var(--shadow);
  backdrop-filter: saturate(180%) blur(18px);
  border-radius: var(--radius);
}

.wallet-card {
  display: grid;
  grid-template-columns: 13px minmax(0, 1fr) auto;
  align-items: center;
  gap: 13px;
  padding: 18px;
  align-self: end;
}

.wallet-card p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 0.88rem;
}

.wallet-button {
  min-height: 34px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: #fff;
  background: var(--accent);
  cursor: pointer;
  font-weight: 850;
}

.status-dot {
  width: 13px;
  height: 13px;
  border-radius: 999px;
  background: var(--ok);
  box-shadow: 0 0 0 7px rgba(36, 160, 111, 0.14);
}

.infra-strip {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 12px;
  margin-bottom: 24px;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
  backdrop-filter: none;
}

.infra-strip div {
  min-height: 112px;
  position: relative;
  padding: 18px;
  border: 1px solid rgba(210, 210, 215, 0.82);
  border-radius: var(--radius);
  background: #fff;
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.04);
}

.infra-strip strong,
.infra-strip span,
.infra-strip small {
  display: block;
}

.infra-strip strong {
  padding-right: 48px;
}

.infra-strip small {
  position: absolute;
  top: 14px;
  right: 14px;
  color: var(--ok);
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
}

