function renderWatchlist() {
  if (!elements.watchlist) return;
  elements.watchlist.innerHTML = reliableWatchlist
    .map(
      (item) => `
        <article class="watch-card">
          <header>
            <div>
              <h3>${item.symbol} · ${item.name}</h3>
              <span class="watch-tag">${item.category}</span>
            </div>
          </header>
          <p>${item.why}</p>
          <p>${t("mainRisks")} ${item.risk}</p>
          <div class="watch-actions">
            <button class="ghost-button" type="button" data-watch="${item.symbol}">${t("createResearch")}</button>
          </div>
        </article>
      `,
    )
    .join("");
}

function renderActiveTask() {
  const workable = state.tasks.find((task) => ["accepted", "running"].includes(task.status));
  const waiting = state.tasks.find((task) => task.status === "submitted");
  const task = workable || waiting || state.tasks.find((item) => item.status === "open");
  elements.activeTask.innerHTML = task
    ? renderTaskCard(task, true)
    : `<article class="task-card"><strong>${t("noActiveWork")}</strong><p>${t("noActiveWorkBody")}</p></article>`;
}

function renderHistory() {
  const history = state.tasks.filter((task) => ["paid", "refunded", "submitted"].includes(task.status));
  elements.historyList.innerHTML =
    history.map((task) => renderTaskCard(task, true)).join("") ||
    `<article class="task-card"><strong>${t("noHistory")}</strong><p>${t("noHistoryBody")}</p></article>`;
}
  if (task.status === "accepted") {
    return `<button class="step-button" type="button" data-action="run" data-id="${task.id}">${t("runSubmit")}</button>`;
  }
  if (task.status === "running") {
    return `<button class="step-button" type="button" data-action="submit" data-id="${task.id}">${t("submitResult")}</button>`;
  }
  if (task.status === "submitted") {
    return `<button class="step-button" type="button" data-action="pay" data-id="${task.id}">${t("approvePayment")}</button>
      <button class="ghost-button" type="button" data-action="refund" data-id="${task.id}">${t("returnEscrow")}</button>`;
  }
  return "";
}

elements.tabs.forEach((tab) => tab.addEventListener("click", () => setView(tab.dataset.view)));
elements.languageSelect.addEventListener("change", () => {
  currentLanguage = elements.languageSelect.value;
  localStorage.setItem(LANGUAGE_KEY, currentLanguage);
  render();
});
elements.templateButtons.forEach((button) =>
  button.addEventListener("click", () => {
    const template = demandTemplates[button.dataset.template];
    if (!template) return;
    elements.taskType.value = template.type;
    elements.taskBudget.value = template.budget;
    elements.taskPrompt.value = template.prompt;
  }),
);

elements.agentForm.addEventListener("submit", (event) => {
  event.preventDefault();
  state.agent = readAgentForm();
  saveState();
  render();
});

function readAgentForm() {
  return {
    ...state.agent,
    name: elements.agentName.value.trim() || "local-agent",
    skill: elements.agentSkill.value,
    runtime: "Online Agent API",
    onlineApiBase: elements.onlineApiBase.value.trim() || "https://api.openai.com/v1",
    onlineModel: elements.onlineModel.value.trim() || "gpt-4.1-mini",
    onlineApiKey: elements.onlineApiKey.value.trim(),
  };
}

elements.taskForm.addEventListener("submit", (event) => {
  event.preventDefault();
  createTask();
});

document.body.addEventListener("click", (event) => {
  const watchButton = event.target.closest("[data-watch]");
  if (watchButton) {
    const item = reliableWatchlist.find((entry) => entry.symbol === watchButton.dataset.watch);
    if (!item) return;
    elements.taskType.value = item.taskType;
    elements.taskBudget.value = item.taskType === "Project deep research" ? "15" : "5";
    elements.taskPrompt.value = `Analyze ${item.symbol} / ${item.name}. Decide whether it is worth watching, and include opportunity score, risk score, main catalysts, key risks, suggested action, and data to monitor.`;
    window.scrollTo({ top: 0, behavior: "smooth" });
    return;
  }

  const button = event.target.closest("[data-action]");
  if (!button) return;
  const { action, id } = button.dataset;
  if (action === "accept") acceptTask(id);
  if (action === "run") runTask(id);
  if (action === "submit") submitTask(id);
  if (action === "pay") payTask(id);
  if (action === "refund") refundTask(id);
});

elements.seedBtn?.addEventListener("click", seedTasks);
elements.resetBtn.addEventListener("click", resetAll);
elements.testOnlineApiBtn.addEventListener("click", testOnlineApi);
elements.connectWalletBtn.addEventListener("click", () => {
  if (state.wallet.mode === "connected" && state.wallet.chainId !== baseChain.chainId) {
    switchToBase();
    return;
  }
  connectWallet();
});

