function renderActiveTask() {
  const workable = state.tasks.find((task) => ["accepted", "running"].includes(task.status));
  const waiting = state.tasks.find((task) => task.status === "submitted");
  const task = workable || waiting || state.tasks.find((item) => item.status === "open");
  elements.activeTask.innerHTML = task
    ? renderTaskCard(task, true)
    : `<article class="task-card"><strong>${t("noActiveWork")}</strong><p>${t("noActiveWorkBody")}</p></article>`;
}

function renderHistory() {
  const history = state.tasks.filter((task) => ["paid", "refunded", "submitted"].includes(task.status));
  elements.historyList.innerHTML =
    history.map((task) => renderTaskCard(task, true)).join("") ||
    `<article class="task-card"><strong>${t("noHistory")}</strong><p>${t("noHistoryBody")}</p></article>`;
}

function renderTaskCard(task, expanded = false) {
  const actions = actionButtons(task);
  const result =
    expanded && task.result
      ? `<div class="message agent-message">
          <span class="message-label">${t("agentResult")}</span>
          <p>${task.result}</p>
          <div class="pill-row">
            <span class="pill">${task.resultUri}</span>
            <span class="pill">${task.resultHash}</span>
            <span class="pill">${task.resultSignature}</span>
          </div>
        </div>`
      : `<div class="message agent-message empty">
          <span class="message-label">${t("agentStatus")}</span>
          <p>${task.executionLog || t("waitingAgent")}</p>
        </div>`;
  const settlement = task.settlementHash ? `<span class="pill">${task.settlementHash}</span>` : "";

  return `
    <article class="task-card status-${task.status}">
      <div class="task-card-head">
        <strong>${task.id} · ${task.type}</strong>
        <span class="status-badge">${statusLabel[task.status] || task.status}</span>
      </div>
      <div class="message-stack">
        <div class="message user-message">
          <span class="message-label">${t("userRequest")}</span>
          <p>${task.prompt}</p>
        </div>
        ${result}
      </div>
      <div class="pill-row">
        <span class="pill">${task.budget} USDC</span>
        <span class="pill">${task.inputHash}</span>
        <span class="pill">${task.publisherSignature}</span>
        ${settlement}
      </div>
      ${actions ? `<div class="action-row">${actions}</div>` : ""}
    </article>
  `;
}

function actionButtons(task) {
  if (task.status === "open") {
    return `<button class="step-button" type="button" data-action="accept" data-id="${task.id}">${t("accept")}</button>
      <button class="ghost-button" type="button" data-action="refund" data-id="${task.id}">${t("refund")}</button>`;
  }
  if (task.status === "accepted") {
    return `<button class="step-button" type="button" data-action="run" data-id="${task.id}">${t("runSubmit")}</button>`;
  }
  if (task.status === "running") {
    return `<button class="step-button" type="button" data-action="submit" data-id="${task.id}">${t("submitResult")}</button>`;
  }
  if (task.status === "submitted") {
    return `<button class="step-button" type="button" data-action="pay" data-id="${task.id}">${t("approvePayment")}</button>
      <button class="ghost-button" type="button" data-action="refund" data-id="${task.id}">${t("returnEscrow")}</button>`;
  }
  return "";
}

elements.tabs.forEach((tab) => tab.addEventListener("click", () => setView(tab.dataset.view)));
elements.languageSelects.forEach((select) => {
  select.addEventListener("change", () => {
    currentLanguage = select.value;
    localStorage.setItem(LANGUAGE_KEY, currentLanguage);
    render();
  });
});

elements.agentForm.addEventListener("submit", (event) => {
  event.preventDefault();
  state.agent = readAgentForm();
  saveState();
  render();
});

elements.profileForm.addEventListener("submit", (event) => {
  event.preventDefault();
  saveProfile();
});

elements.relationForm.addEventListener("submit", (event) => {
  event.preventDefault();
  createRelationship();
});

elements.messageForm.addEventListener("submit", (event) => {
  event.preventDefault();
  sendMessage();
});

function readAgentForm() {
  return {
    ...state.agent,
    name: elements.agentName.value.trim() || "local-agent",
    skill: elements.agentSkill.value,
    runtime: "Online Agent API",
    onlineApiBase: elements.onlineApiBase.value.trim() || "https://api.openai.com/v1",
    onlineModel: elements.onlineModel.value.trim() || "gpt-4.1-mini",
    onlineApiKey: elements.onlineApiKey.value.trim(),
  };
}

elements.taskForm.addEventListener("submit", (event) => {
  event.preventDefault();
  createTask();
});

document.body.addEventListener("click", (event) => {
  const button = event.target.closest("[data-action]");
  if (!button) return;
  const { action, id } = button.dataset;
  if (action === "accept") acceptTask(id);
  if (action === "run") runTask(id);
  if (action === "submit") submitTask(id);
  if (action === "pay") payTask(id);
  if (action === "refund") refundTask(id);
});

elements.resetBtn.addEventListener("click", resetAll);
elements.testOnlineApiBtn.addEventListener("click", testOnlineApi);
elements.connectWalletBtn.addEventListener("click", () => {
  if (state.wallet.mode === "connected" && state.wallet.chainId !== baseChain.chainId) {
    switchToBase();
    return;
  }
  connectWallet();
});

if (hasInjectedWallet()) {
  window.ethereum.on?.("accountsChanged", (accounts) => {
    state.wallet.connectedAddress = accounts[0] || "";
    state.wallet.mode = accounts[0] ? "connected" : "local";
    saveState();
    render();
  });
  window.ethereum.on?.("chainChanged", (chainId) => {
    state.wallet.chainId = chainId;
    saveState();
    render();

}

function addRelationship(type, target, note = "") {
  const cleanTarget = target.trim();
  if (!cleanTarget) return;
  const record = {
    id: `rel_${String(Date.now()).slice(-7)}`,
    user: state.wallet.connectedAddress || state.wallet.address,
    target: cleanTarget,
    relationType: type,
    refHash: hashPayload({ type, target: cleanTarget, note }),
    note,
    timestamp: new Date().toLocaleString("en-US"),
  };
  state.relationships = [
    record,
    ...state.relationships.filter((item) => !(item.target === cleanTarget && item.relationType === type)),
  ];
  saveState();
  render();
}

function createRelationship() {
  addRelationship(elements.relationType.value, elements.relationTarget.value, elements.relationNote.value.trim());
  elements.relationTarget.value = "";
  elements.relationNote.value = "";
}

function sendMessage() {
  const recipient = elements.messageTo.value.trim();
  const body = elements.messageBody.value.trim();
  if (!recipient || !body) return;
  const envelope = {
    id: `msg_${String(Date.now()).slice(-7)}`,
    from: state.wallet.connectedAddress || state.wallet.address,
    to: recipient,
    route: elements.messageRoute.value,
    body,
    encrypted: `sealed:${hashPayload({ recipient, body, route: elements.messageRoute.value }).slice(2)}`,
    timestamp: new Date().toLocaleString("en-US"),
  };
  state.messages.unshift(envelope);
  addRelationship("contact", recipient, `Message via ${envelope.route}`);
  elements.messageTo.value = "";
  elements.messageBody.value = "";
}

function updateTask(id, next) {
  state.tasks = state.tasks.map((task) => (task.id === id ? { ...task, ...next } : task));
}

function acceptTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "open") return;
  updateTask(id, {
    status: "accepted",
    worker: state.agent.name,
    acceptSignature: sign({ taskId: id, action: "accept" }),
  });
  saveState();
  setView("agent");
}

async function runTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "accepted") return;
  updateTask(id, {
    status: "running",
    executionLog: `${state.agent.runtime} is running ${task.type}.`,
  });
  saveState();
  render();

  const result = await generateWithAgent(task);
  const resultHash = hashPayload({ taskId: id, result, agent: state.agent.id });
  updateTask(id, {
    status: "submitted",
    result,
    resultUri: `r2-ipfs://${id}.json`,
    resultHash,
    resultSignature: sign({ taskId: id, resultHash }),
  });
  saveState();
  render();
}

function submitTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "running") return;
  const result = buildResult(task);
  const resultHash = hashPayload({ taskId: id, result, agent: state.agent.id });
  updateTask(id, {
    status: "submitted",
    result,
    resultUri: `r2-ipfs://${id}.json`,
    resultHash,
    resultSignature: sign({ taskId: id, resultHash }),
  });
  saveState();
  render();
}

async function generateWithAgent(task) {
  try {
    return await callOnlineApi(task);
  } catch (error) {
    state.agent.modelStatus = `Online agent failed; using fallback result: ${error.message}`;
    return buildResult(task);
  }
}

async function callOnlineApi(task) {
  const baseUrl = state.agent.onlineApiBase.replace(/\/$/, "");
  if (!state.agent.onlineApiKey) throw new Error("Missing API key");
  const response = await fetch(`${baseUrl}/chat/completions`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${state.agent.onlineApiKey}`,
    },
    body: JSON.stringify({
      model: state.agent.onlineModel,
      messages: [
        {
          role: "system",
          content:
            "You are OneNode's Web3 investment and yield research agent. Produce a decision-oriented report with conclusion, opportunity score, risk score, suggested action, key reasons, risks, and data to monitor. Do not promise returns.",
        },
        {
          role: "user",
          content: `Request type: ${task.type}\nRequest: ${task.prompt}`,
        },
      ],
      temperature: 0.3,
    }),
  });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const data = await response.json();
  const text = data.choices?.[0]?.message?.content?.trim();
  if (!text) throw new Error("No model output");
  state.agent.modelStatus = `Connected ${state.agent.onlineModel}`;
  return text;
}

async function testOnlineApi() {
  state.agent = readAgentForm();
  state.agent.modelStatus = "Testing online API...";
  saveState();
  render();

  try {
    const text = await callOnlineApi({
      type: "Connection test",
      prompt: "Reply with one short sentence: OneNode online agent connected.",
    });
    state.agent.modelStatus = text ? `Online API ready: ${state.agent.onlineModel}` : "Online API returned no content";
  } catch (error) {
    state.agent.modelStatus = `On…2511 chars truncated…ions and avoid high slippage, high gas, or long lock-up tasks.",
  };
