function renderSelectLabels(select, labels) {
  [...select.options].forEach((option) => {
    option.textContent = labels[option.value] || option.value;
  });
}

function renderNavigation() {
  document.body.dataset.view = state.view;
  elements.tabs.forEach((tab) => tab.classList.toggle("active", tab.dataset.view === state.view));
  elements.panels.forEach((panel) => panel.classList.toggle("hidden", panel.dataset.panel !== state.view));
}

function renderForms() {
  elements.agentName.value = state.agent.name;
  elements.agentSkill.value = state.agent.skill;
  elements.onlineApiBase.value = state.agent.onlineApiBase;
  elements.onlineModel.value = state.agent.onlineModel;
  elements.onlineApiKey.value = state.agent.onlineApiKey;
  elements.profileName.value = state.profile.name;
  elements.profileBio.value = state.profile.bio;
  elements.profileAgentId.value = state.profile.agentId;
  elements.profileXmtp.value = state.profile.xmtp;
  elements.profileWaku.value = state.profile.wakuTopic;
}

