  elements.agentCard.innerHTML = `
    <strong>${state.agent.name}</strong>
    <p>${state.agent.skill} · Online Agent API</p>
    <div class="pill-row">
      <span class="pill">${state.agent.id}</span>
      <span class="pill">ERC-8004 ready</span>
      <span class="pill">${state.agent.modelStatus}</span>
    </div>
  `;
}

function renderProfile() {
  elements.profileCard.innerHTML = `
    <strong>${state.profile.name}</strong>
    <p>${state.profile.bio || "No profile bio yet."}</p>
    <div class="pill-row">
      <span class="pill">${state.profile.agentId}</span>
