    </div>
  `;
}

function renderRelationships() {
  elements.relationSummary.textContent = `${state.relationships.length} records`;
  elements.relationList.innerHTML =
    state.relationships
      .map(
        (record) => `
          <article class="task-card">
            <div class="task-card-head">
              <strong>${record.relationType.toUpperCase()} · ${record.target}</strong>
              <span class="status-badge">${record.timestamp}</span>
            </div>
            <p>${record.note || "Relationship record"}</p>
            <div class="pill-row">
              <span class="pill">${record.user}</span>
              <span class="pill">${record.refHash}</span>
            </div>
          </article>
        `,
      )
      .join("") || `<article class="task-card"><strong>No relationships yet</strong><p>Follow, trust, block, message, or collaborate to create records.</p></article>`;
}

function renderMessages() {
